#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/*
 * Re‑implementation of the original "prog23_longest_common_prefix" binary.
 *
 * Behaviour (derived from reverse‑engineering):
 *   • If the number of arguments after the program name exceeds 64, print
 *     "TOO_MANY" and exit.
 *   • If no arguments are supplied, print "EMPTY" and exit.
 *   • If any argument is longer than 1024 characters, print "TOO_LONG" and exit.
 *   • Otherwise compute the longest common prefix of all arguments (argv[1] …
 *     argv[argc‑1]).
 *       – If the common prefix becomes empty, print "EMPTY" and exit.
 *       – If a non‑empty prefix exists, print it followed by a newline.
 *   All messages are printed to stdout and the program exits with status 0.
 */

#define MAX_ARGS   64          /* maximum number of strings after program name */
#define MAX_LEN    1024        /* maximum allowed length of each string */

/* Helper: print a message and terminate with exit status 0 */
static void finish(const char *msg)
{
    puts(msg);
    exit(0);
}

/* Compute the longest common prefix of the supplied arguments.
 * The result is stored in `out`, which must be able to hold MAX_LEN+1 bytes.
 */
static void longest_common_prefix(int argc, char **argv, char *out)
{
    if (argc <= 1) {               /* no strings supplied */
        finish("EMPTY");
    }

    /* Initialise the prefix with the first argument */
    const char *first = argv[1];
    size_t pref_len = strlen(first);
    if (pref_len > MAX_LEN) {
        finish("TOO_LONG");
    }
    memcpy(out, first, pref_len);
    out[pref_len] = '\0';

    /* Compare the current prefix with each subsequent argument */
    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t len = strlen(s);
        if (len > MAX_LEN) {
            finish("TOO_LONG");
        }

        /* Reduce the prefix length until it matches the current string */
        while (pref_len > 0 && (pref_len > len || strncmp(out, s, pref_len) != 0)) {
            --pref_len;
        }
        out[pref_len] = '\0';   /* truncate the prefix */
        if (pref_len == 0) {
            finish("EMPTY");
        }
    }
}

int main(int argc, char **argv)
{
    /* Argument count check (excluding program name) */
    if (argc - 1 > MAX_ARGS) {
        finish("TOO_MANY");
    }

    char prefix[MAX_LEN + 1];
    longest_common_prefix(argc, argv, prefix);

    /* Non‑empty common prefix found */
    puts(prefix);
    return 0;
}
